syntax:
int x = 10;
int* p = &x;  // p lưu địa chỉ của x
*p = 25;      // Sửa giá trị của x thành 25

example:
#include <iostream>
int main() {
    int a = 42;
    int* ptr = &a;
    std::cout << "Dia chi: " << ptr << ", Gia tri: " << *ptr << '\n';
}

#include <iostream>
int main() {
    int x = 10;
    int& r = x;
    r += 5;
    std::cout << x << '\n'; // 15
}

syntax:
int* p = arr;
*(p + i)  // Tương đương hoàn toàn với arr[i]
p++;      // Nhảy sang phần tử kế tiếp

example:
#include <iostream>
int main() {
    int a[3] = {10, 20, 30};
    int* p = a;
    for (int i = 0; i < 3; ++i) {
        std::cout << *(p + i) << ' '; // 10 20 30
    }
}

syntax:
int* p = new int(5);
delete p;

int* arr = new int[n];
delete[] arr;

example:
#include <iostream>
int main() {
    int n = 3;
    int* a = new int[n];
    for (int i = 0; i < n; ++i) a[i] = (i + 1) * 10;
    std::cout << a[2] << '\n'; // 30
    delete[] a;
    a = NULL;
}
